#include <stdio.h>
#include <string.h>

enum LineStatus { LINE_END, LINE_OK, LINE_LONG, LINE_BAD, LINE_IO };

/* Read one full record. capacity includes a slot for '\0'. */
static enum LineStatus read_line(char text[], size_t capacity)
{
    size_t used = 0;
    int overflow = 0;
    int contains_nul = 0;
    int byte = getchar();

    if (byte == EOF) {
        return ferror(stdin) ? LINE_IO : LINE_END;
    }

    while (byte != '\n' && byte != EOF) {
        int next = getchar();
        if (!(byte == '\r' && next == '\n')) {
            if (byte == 0) {
                contains_nul = 1;
            }
            if (used + 1 < capacity) {
                ((unsigned char *)text)[used++] = (unsigned char)byte;
            } else {
                overflow = 1;
            }
        }
        byte = next;
    }
    text[used] = '\0';
    if (ferror(stdin)) {
        return LINE_IO;
    }
    if (contains_nul) {
        return LINE_BAD;
    }
    return overflow ? LINE_LONG : LINE_OK;
}

int main(void)
{
    char line[13];
    size_t rejected = 0;
    for (;;) {
        enum LineStatus status = read_line(line, sizeof line);
        if (status == LINE_END) {
            break;
        }
        if (status == LINE_IO) {
            fputs("input error\n", stderr);
            return 1;
        }
        if (status != LINE_OK) {
            ++rejected;
            continue;
        }

        /* TODO: match the prefix at the start of the line. */
        if (strcmp(line, "ERR") == 0) {
            puts(line);
        }
    }
    printf("rejected %zu\n", rejected);
    return 0;
}

